'use client';

import { Wrench } from 'lucide-react';
import { useRef, useState } from 'react';
import { Badge } from '@/components/ui/badge';
import type { TranscriptEntry } from '@/lib/api/types';
import { cn } from '@/lib/cn';
import { formatOffset } from '@/lib/format';

const SPEAKER: Record<TranscriptEntry['role'], string> = { user: 'Caller', assistant: 'Assistant', tool: 'Tool', system: 'System' };

/**
 * The entry being heard at `positionMs`: the last one that started at or before it. Entries without
 * an offset are never active.
 */
export function activeEntryAt(entries: TranscriptEntry[], positionMs: number): number | null {
  let active: TranscriptEntry | null = null;
  for (const entry of entries) {
    if (entry.startOffsetMs === null || entry.startOffsetMs > positionMs) continue;
    if (!active || entry.startOffsetMs >= (active.startOffsetMs ?? 0)) active = entry;
  }
  return active?.seq ?? null;
}

/**
 * The call's transcript, turn by turn, with tool calls where the model asked for them. With a
 * recording, the line being played is highlighted as the audio plays, and choosing a line's time jumps
 * the audio there.
 */
export function TranscriptView({ entries, recordingUrl, live }: { entries: TranscriptEntry[]; recordingUrl: string | null; live?: boolean }) {
  const audioRef = useRef<HTMLAudioElement>(null);
  const [positionMs, setPositionMs] = useState<number | null>(null);
  const active = positionMs === null ? null : activeEntryAt(entries, positionMs);

  function seek(entry: TranscriptEntry) {
    const audio = audioRef.current;
    if (!audio || entry.startOffsetMs === null) return;
    audio.currentTime = entry.startOffsetMs / 1000;
    setPositionMs(entry.startOffsetMs);
    void audio.play().catch(() => undefined);
  }

  return (
    <div className="flex flex-col gap-4">
      {recordingUrl ? (
        // eslint-disable-next-line jsx-a11y/media-has-caption -- audio only: the synced transcript below is its text alternative (WCAG 1.2.1)
        <audio
          ref={audioRef}
          controls
          preload="metadata"
          src={recordingUrl}
          aria-label="Call recording"
          className="w-full"
          onTimeUpdate={(event) => setPositionMs(event.currentTarget.currentTime * 1000)}
        />
      ) : (
        <p className="rounded-md border border-border bg-surface-2 px-3 py-2 text-sm text-muted">No recording for this call. Recordings are not stored yet; the transcript below is.</p>
      )}
      {entries.length === 0 ? (
        <p className="text-sm text-muted">{live ? 'Nothing said yet. The transcript fills in as the call goes on.' : 'Nothing was said on this call.'}</p>
      ) : (
        <ol aria-label="Transcript" className="flex flex-col gap-2">
          {entries.map((entry) => {
            const isActive = active === entry.seq;
            const time = formatOffset(entry.startOffsetMs);
            return (
              <li
                key={entry.id}
                aria-current={isActive ? 'true' : undefined}
                className={cn(
                  'flex gap-3 rounded-md border px-3 py-2',
                  isActive ? 'border-accent bg-accent-soft' : 'border-transparent',
                  entry.role === 'user' ? 'bg-surface-2' : undefined
                )}
              >
                <div className="w-12 shrink-0 pt-0.5 text-xs text-muted tabular-nums">
                  {recordingUrl && entry.startOffsetMs !== null ? (
                    <button type="button" onClick={() => seek(entry)} className="rounded text-accent-text underline-offset-2 hover:underline" aria-label={`Play from ${time}, ${entry.kind === 'tool-call' ? `tool call ${entry.toolCall?.name ?? ''}` : SPEAKER[entry.role].toLowerCase()}`}>
                      {time}
                    </button>
                  ) : (
                    time
                  )}
                </div>
                <div className="min-w-0 flex-1">
                  {entry.kind === 'tool-call' && entry.toolCall ? (
                    <div className="flex flex-col gap-1">
                      <div className="flex flex-wrap items-center gap-2 text-sm">
                        <Wrench aria-hidden="true" className="size-4 text-muted" />
                        <span className="font-medium text-text">Tool call: {entry.toolCall.name}</span>
                        <Badge tone={entry.toolCall.status === 'succeeded' ? 'success' : entry.toolCall.status === 'failed' ? 'danger' : 'neutral'}>{entry.toolCall.status}</Badge>
                      </div>
                      <details className="text-xs">
                        <summary className="cursor-pointer text-muted">Arguments{entry.toolCall.result !== null && entry.toolCall.result !== undefined ? ' and result' : ''}</summary>
                        <pre className="mt-1 overflow-x-auto rounded bg-surface-2 p-2 font-mono text-text">{JSON.stringify(entry.toolCall.arguments, null, 2)}</pre>
                        {entry.toolCall.result !== null && entry.toolCall.result !== undefined ? <pre className="mt-1 overflow-x-auto rounded bg-surface-2 p-2 font-mono text-text">{JSON.stringify(entry.toolCall.result, null, 2)}</pre> : null}
                      </details>
                    </div>
                  ) : (
                    <>
                      <div className="text-xs font-semibold text-muted">
                        {SPEAKER[entry.role]}
                        {entry.interrupted ? <span className="ml-2 font-normal">(cut off by the caller; this is what they heard)</span> : null}
                      </div>
                      <p className="text-sm break-words whitespace-pre-wrap text-text">{entry.text}</p>
                    </>
                  )}
                </div>
              </li>
            );
          })}
        </ol>
      )}
    </div>
  );
}
