'use client';

import { RotateCw } from 'lucide-react';
import Link from 'next/link';
import { useState } from 'react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardBody, CardHeader, Stat } from '@/components/ui/card';
import { InlineField } from '@/components/ui/field';
import { PageBody, PageHeader } from '@/components/ui/page';
import { ErrorState, LoadingState } from '@/components/ui/states';
import { Switch } from '@/components/ui/switch';
import { Table, TBody, Td, Th, THead, Tr } from '@/components/ui/table';
import { Tabs } from '@/components/ui/tabs';
import { useToast } from '@/components/ui/toast';
import type { AnalysisView, CallDetail as Call, UsageRecord } from '@/lib/api/types';
import { formatDateTime, formatDuration, formatNumber, formatOffset, humanize } from '@/lib/format';
import { useSession } from '@/lib/session';
import { useCall, useRerunAnalysis } from './api';
import { StatusBadge, SuccessBadge } from './call-list';
import { TranscriptView } from './transcript-view';

/** Timeline events that are diagnostics rather than what happened on the call (shown on request). */
const DEBUG_EVENTS = new Set(['log', 'transcript-partial', 'llm-request', 'llm-response', 'state']);
const LIVE = ['queued', 'ringing', 'in-progress'];

export function CallDetail({ id }: { id: string }) {
  const query = useCall(id);
  if (query.isPending) {
    return (
      <PageBody>
        <LoadingState label="Loading call…" rows={5} />
      </PageBody>
    );
  }
  if (query.isError) {
    return (
      <PageBody>
        <ErrorState error={query.error} title="Could not load this call" onRetry={() => void query.refetch()} />
      </PageBody>
    );
  }
  return <LoadedCall call={query.data} />;
}

function durationOf(call: Call): number | null {
  if (!call.startedAt) return null;
  const end = call.endedAt ? Date.parse(call.endedAt) : Date.now();
  return end - Date.parse(call.startedAt);
}

export function LoadedCall({ call }: { call: Call }) {
  const [tab, setTab] = useState('overview');
  const live = LIVE.includes(call.status);
  const toolCalls = call.transcript.filter((e) => e.kind === 'tool-call');
  return (
    <PageBody wide>
      <PageHeader
        breadcrumb={
          <Link href="/calls" className="underline-offset-4 hover:underline">
            Calls
          </Link>
        }
        title={`${call.assistantName} · ${formatDateTime(call.startedAt ?? call.createdAt)}`}
        description={
          <span className="flex flex-wrap items-center gap-2">
            <StatusBadge status={call.status} endReason={call.endReason} />
            <span className="capitalize">{call.direction}</span>
            {call.customerNumber ? <span>· {call.customerNumber}</span> : null}
            {live ? <span aria-live="polite">· Live: this page refreshes every few seconds</span> : null}
          </span>
        }
      />
      <dl className="mb-6 grid grid-cols-2 gap-3 md:grid-cols-4">
        <Stat label="Duration" value={formatDuration(durationOf(call))} />
        <Stat label="Turns" value={formatNumber(call.transcript.filter((e) => e.kind === 'speech').length)} />
        <Stat label="Tool calls" value={formatNumber(toolCalls.length)} />
        <Stat label="Success" value={<SuccessBadge analysis={call.analysis} />} />
      </dl>
      <Tabs
        label="Call details"
        value={tab}
        onValueChange={setTab}
        items={[
          { value: 'overview', label: 'Overview', content: <Overview call={call} /> },
          { value: 'transcript', label: 'Transcript', badge: <Badge>{call.transcript.length}</Badge>, content: <TranscriptView entries={call.transcript} recordingUrl={call.recordingUrl} live={live} /> },
          { value: 'timeline', label: 'Timeline', content: <Timeline call={call} /> },
        ]}
      />
    </PageBody>
  );
}

function Overview({ call }: { call: Call }) {
  return (
    // grid-cols-1 is minmax(0, 1fr): a wide table scrolls inside its card instead of widening the page
    <div className="grid grid-cols-1 items-start gap-5 lg:grid-cols-2">
      <AnalysisCard call={call} />
      <div className="flex min-w-0 flex-col gap-5">
        <ToolCallsCard call={call} />
        <CostCard usage={call.cost} analysis={call.analysis} />
        <Card>
          <CardHeader title="Call" />
          <CardBody>
            <dl className="grid grid-cols-[max-content_1fr] gap-x-4 gap-y-2 text-sm">
              <dt className="text-muted">Call id</dt>
              <dd className="font-mono break-all">{call.id}</dd>
              {call.providerCallId ? (
                <>
                  <dt className="text-muted">Provider call id</dt>
                  <dd className="font-mono break-all">{call.providerCallId}</dd>
                </>
              ) : null}
              <dt className="text-muted">Created</dt>
              <dd>{formatDateTime(call.createdAt)}</dd>
              <dt className="text-muted">Ended</dt>
              <dd>{call.endedAt ? formatDateTime(call.endedAt) : '—'}</dd>
              <dt className="text-muted">End reason</dt>
              <dd>{humanize(call.endReason)}</dd>
              {call.assistantId ? (
                <>
                  <dt className="text-muted">Assistant</dt>
                  <dd>
                    <Link href={`/assistants/${call.assistantId}`} className="text-accent-text underline-offset-4 hover:underline">
                      {call.assistantName}
                    </Link>
                  </dd>
                </>
              ) : null}
            </dl>
          </CardBody>
        </Card>
      </div>
    </div>
  );
}

function analysisTone(status: AnalysisView['status']) {
  return status === 'succeeded' ? 'success' : status === 'failed' ? 'danger' : status === 'skipped' ? 'neutral' : 'info';
}

export function AnalysisCard({ call }: { call: Call }) {
  const { can } = useSession();
  const toast = useToast();
  const rerun = useRerunAnalysis(call.id);
  const analysis = call.analysis;
  const busy = analysis?.status === 'pending' || analysis?.status === 'running';
  const ended = !LIVE.includes(call.status);
  return (
    <Card>
      <CardHeader
        title="Analysis"
        description={analysis ? <Badge tone={analysisTone(analysis.status)}>{humanize(analysis.status)}</Badge> : 'Runs when the call ends'}
        actions={
          can('calls:create') && ended ? (
            <Button
              size="sm"
              loading={rerun.isPending}
              disabled={busy}
              onClick={() =>
                rerun.mutate(undefined, {
                  onSuccess: () => toast.success('Analysis queued again'),
                  onError: (error) => toast.error('Could not re-run the analysis', error),
                })
              }
            >
              <RotateCw aria-hidden="true" />
              Re-run
            </Button>
          ) : null
        }
      />
      <CardBody className="flex flex-col gap-4 text-sm">
        {!analysis ? (
          <p className="text-muted">{ended ? 'No analysis for this call.' : 'The call is still going; it is analysed once it ends.'}</p>
        ) : analysis.status === 'skipped' ? (
          <p className="text-muted">{analysis.skipReason === 'no-transcript' ? 'Skipped: nothing was said on this call.' : 'Skipped: the assistant has no analysis steps turned on.'}</p>
        ) : busy ? (
          <p className="text-muted">Analysing…{analysis.attempts > 1 ? ` (attempt ${analysis.attempts})` : ''}</p>
        ) : (
          <>
            {analysis.error ? <p className="text-danger">{analysis.error}</p> : null}
            <section aria-labelledby="summary-heading">
              <h3 id="summary-heading" className="font-semibold text-text">
                Summary
              </h3>
              <p className="mt-1 text-text">{analysis.summary ?? analysis.summaryError ?? '—'}</p>
            </section>
            {analysis.successEvaluation ? (
              <section aria-labelledby="success-heading">
                <h3 id="success-heading" className="font-semibold text-text">
                  Success ({humanize(analysis.successEvaluation.rubric)})
                </h3>
                <div className="mt-1 flex items-center gap-2">
                  <SuccessBadge analysis={analysis} />
                  <span className="text-muted">{analysis.successEvaluation.reason ?? analysis.successEvaluation.error ?? ''}</span>
                </div>
              </section>
            ) : null}
            {analysis.structuredOutputs.length ? (
              <section aria-labelledby="outputs-heading">
                <h3 id="outputs-heading" className="font-semibold text-text">
                  Structured outputs
                </h3>
                <ul className="mt-1 flex flex-col gap-3">
                  {analysis.structuredOutputs.map((output) => (
                    <li key={output.id ?? output.name} className="rounded-md border border-border p-3">
                      <div className="flex items-center gap-2">
                        <span className="font-medium">{output.name}</span>
                        <Badge tone={analysisTone(output.status)}>{humanize(output.status)}</Badge>
                      </div>
                      {output.values ? (
                        <dl className="mt-2 grid grid-cols-[max-content_1fr] gap-x-4 gap-y-1">
                          {Object.entries(output.values).map(([key, value]) => (
                            <div key={key} className="contents">
                              <dt className="font-mono text-xs text-muted">{key}</dt>
                              <dd className="break-words">{typeof value === 'object' ? JSON.stringify(value) : String(value)}</dd>
                            </div>
                          ))}
                        </dl>
                      ) : output.error ? (
                        <p className="mt-1 text-danger">{output.error}</p>
                      ) : null}
                    </li>
                  ))}
                </ul>
              </section>
            ) : null}
          </>
        )}
      </CardBody>
    </Card>
  );
}

function ToolCallsCard({ call }: { call: Call }) {
  const tools = call.transcript.filter((e) => e.kind === 'tool-call' && e.toolCall);
  return (
    <Card>
      <CardHeader title="Tool calls" />
      <CardBody>
        {tools.length === 0 ? (
          <p className="text-sm text-muted">The assistant called no tools.</p>
        ) : (
          <ul className="flex flex-col gap-2 text-sm">
            {tools.map((entry) => (
              <li key={entry.id} className="flex flex-wrap items-center gap-2">
                <span className="w-12 text-xs text-muted tabular-nums">{formatOffset(entry.startOffsetMs)}</span>
                <span className="font-medium">{entry.toolCall?.name}</span>
                <Badge>{entry.toolCall?.status}</Badge>
                <code className="min-w-0 truncate font-mono text-xs text-muted">{JSON.stringify(entry.toolCall?.arguments)}</code>
              </li>
            ))}
          </ul>
        )}
      </CardBody>
    </Card>
  );
}

function units(record: UsageRecord): string {
  const u = record.units;
  const parts: string[] = [];
  if (u.audioSeconds) parts.push(`${formatNumber(u.audioSeconds, 1)} s audio in`);
  if (u.inputTokens || u.outputTokens) parts.push(`${formatNumber(u.inputTokens ?? 0)} in / ${formatNumber(u.outputTokens ?? 0)} out tokens`);
  if (u.characters) parts.push(`${formatNumber(u.characters)} characters`);
  if (u.audioSecondsOut) parts.push(`${formatNumber(u.audioSecondsOut, 1)} s audio out`);
  if (u.requests) parts.push(`${formatNumber(u.requests)} requests`);
  return parts.join(', ') || '—';
}

/** Provider usage per component. Prices arrive with billing; these are the units it will be priced on. */
export function CostCard({ usage, analysis }: { usage: UsageRecord[] | null; analysis: AnalysisView | null }) {
  return (
    <Card>
      <CardHeader title="Usage" description="Provider units used by this call. Prices are not shown yet." />
      <CardBody>
        {!usage?.length ? (
          <p className="text-sm text-muted">No usage recorded{analysis?.usage.requests ? ' for the call itself' : ''}.</p>
        ) : (
          <Table label="Usage by component">
            <THead>
              <Tr>
                <Th>Component</Th>
                <Th>Provider</Th>
                <Th>Units</Th>
                <Th>Key</Th>
              </Tr>
            </THead>
            <TBody>
              {usage.map((record, index) => (
                <Tr key={index}>
                  <Td>
                    {humanize(record.component)}
                    {record.fallback ? <Badge tone="warning" className="ml-2">Fallback</Badge> : null}
                  </Td>
                  <Td className="text-muted">
                    {record.provider} / {record.model}
                  </Td>
                  <Td>
                    {units(record)}
                    {record.estimated ? <span className="text-muted"> (estimated)</span> : null}
                  </Td>
                  <Td>{record.billing === 'customer' ? 'Yours' : 'Platform'}</Td>
                </Tr>
              ))}
            </TBody>
          </Table>
        )}
        {analysis?.usage.requests ? (
          <p className="mt-3 text-xs text-muted">
            Analysis: {formatNumber(analysis.usage.requests)} model requests, {formatNumber(analysis.usage.inputTokens)} in / {formatNumber(analysis.usage.outputTokens)} out tokens.
          </p>
        ) : null}
      </CardBody>
    </Card>
  );
}

function payloadSummary(type: string, payload: Record<string, unknown>): string {
  switch (type) {
    case 'turn': {
      const latency = payload.latency as Record<string, number | undefined> | undefined;
      return `${humanize(String(payload.kind))}${payload.interrupted ? ', interrupted' : ''}${latency?.voiceToVoiceMs !== undefined ? `, ${formatNumber(latency.voiceToVoiceMs)} ms voice to voice` : ''}`;
    }
    case 'ended':
      return `${humanize(String(payload.reason))}${payload.transferredTo ? ` to ${String(payload.transferredTo)}` : ''}`;
    case 'error':
    case 'provider-error':
      return `${String(payload.stage ?? '')}: ${String(payload.message ?? '')}`;
    case 'tool-call':
      return String(payload.name ?? '');
    case 'dtmf':
      return `Key ${String(payload.digit ?? '')}`;
    case 'interrupted':
      return payload.heardText ? `Heard: “${String(payload.heardText)}”` : '';
    case 'log':
      return String(payload.msg ?? '');
    default: {
      const text = JSON.stringify(payload);
      return text === '{}' ? '' : text.length > 160 ? `${text.slice(0, 160)}…` : text;
    }
  }
}

export function Timeline({ call }: { call: Call }) {
  const [debug, setDebug] = useState(false);
  const start = Date.parse(call.startedAt ?? call.createdAt);
  const events = call.timeline.filter((e) => debug || !DEBUG_EVENTS.has(e.type));
  const hidden = call.timeline.length - call.timeline.filter((e) => !DEBUG_EVENTS.has(e.type)).length;
  return (
    <div className="flex flex-col gap-4">
      <InlineField label="Show diagnostic events" description={`Log lines, partial transcripts, LLM requests and state changes (${hidden})`}>
        {(props) => <Switch {...props} checked={debug} onCheckedChange={setDebug} />}
      </InlineField>
      {events.length === 0 ? (
        <p className="text-sm text-muted">No events yet.</p>
      ) : (
        <Table label="Call timeline">
          <THead>
            <Tr>
              <Th>Time</Th>
              <Th>Event</Th>
              <Th>Details</Th>
            </Tr>
          </THead>
          <TBody>
            {events.map((event) => (
              <Tr key={event.id}>
                <Td className="text-muted tabular-nums">{formatOffset(Date.parse(event.createdAt) - start)}</Td>
                <Td className="whitespace-nowrap">{humanize(event.type)}</Td>
                <Td className="max-w-xl break-words text-muted">{payloadSummary(event.type, event.payload)}</Td>
              </Tr>
            ))}
          </TBody>
        </Table>
      )}
    </div>
  );
}
